examples:
// Function to calculate whether a current year is a leap year
integer
is_leap_year
(
integer
year
)
{
if
(
year
%
4
)
return
FALSE
;
// Not a leap year under any circumstances
if
(
year
<=
1582
)
return
TRUE
;
// In the Julian calender before 24 February 1582, every fourth year was a leap year
if
(
!
(
year
%
400
))
return
TRUE
;
// A leap century is a leap year if divisible by 400
if
(
!
(
year
%
100
))
return
FALSE
;
// Any other century is not a leap year
return
TRUE
;
// It is divisible by 4 and not a century and not Julian, therefore it is a leap year
}
